//! Bit-exact parity for the battery cost model.
//!
//! The fixture is generated by `scripts/capture_battery_fixture.py`, which
//! calls the reference and reads its results back rather than recomputing the
//! formulas -- a generator that recomputed them would agree with a port that
//! shared its author's misreading while both disagreed with Python.
//!
//! These are closed-form scalar expressions with no summation order to differ
//! on, so parity is asserted **exactly**, as it was for the sensor error
//! model. A tolerance here would hide a wrong constant.

use argusnet_planning::battery::{BatteryModel, BatteryState};
use serde::Deserialize;

#[derive(Deserialize)]
struct Fixture {
    default_safety_margin: String,
    travel: Vec<TravelCase>,
    climb: Vec<ClimbCase>,
    segment: Vec<SegmentCase>,
    return_home: Vec<ReturnHomeCase>,
    consume: Vec<ConsumeCase>,
}

#[derive(Deserialize)]
struct ModelSpec {
    capacity_wh: String,
    hover_power_w: String,
    travel_power_w: String,
    climb_power_w: String,
    cruise_speed_m_per_s: String,
    climb_speed_m_per_s: String,
    reserve_fraction: String,
}

#[derive(Deserialize)]
struct TravelCase {
    model: ModelSpec,
    distance_m: String,
    expected: String,
}

#[derive(Deserialize)]
struct ClimbCase {
    model: ModelSpec,
    delta_z_m: String,
    expected: String,
}

#[derive(Deserialize)]
struct SegmentCase {
    model: ModelSpec,
    start: [String; 3],
    end: [String; 3],
    expected: String,
}

#[derive(Deserialize)]
struct ReturnHomeCase {
    model: ModelSpec,
    position: [String; 3],
    home: [String; 3],
    wind: Option<[String; 3]>,
    expected_return_cost_wh: String,
    expected_dynamic_reserve_wh: String,
    static_reserve_wh: String,
    /// Reported by the generator so the coverage checks below can prove which
    /// branch each case lands in. Never compared against the port -- the costs
    /// are what parity is asserted on.
    horizontal_distance_m: String,
    ground_speed_m_per_s: String,
}

#[derive(Deserialize)]
struct ConsumeCase {
    before_remaining_wh: String,
    before_timestamp_s: String,
    cost_wh: String,
    after_remaining_wh: String,
    after_timestamp_s: String,
}

fn f(text: &str) -> f64 {
    text.parse().expect("fixture float")
}

fn triple(values: &[String; 3]) -> [f64; 3] {
    [f(&values[0]), f(&values[1]), f(&values[2])]
}

fn model(spec: &ModelSpec) -> BatteryModel {
    BatteryModel {
        capacity_wh: f(&spec.capacity_wh),
        hover_power_w: f(&spec.hover_power_w),
        travel_power_w: f(&spec.travel_power_w),
        climb_power_w: f(&spec.climb_power_w),
        cruise_speed_m_per_s: f(&spec.cruise_speed_m_per_s),
        climb_speed_m_per_s: f(&spec.climb_speed_m_per_s),
        reserve_fraction: f(&spec.reserve_fraction),
    }
}

fn load() -> Fixture {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../tests/fixtures/battery_costs.json"
    );
    serde_json::from_str(&std::fs::read_to_string(path).expect("fixture readable"))
        .expect("fixture parses")
}

/// Bit-exact, not approximate. `assert_eq!` on `f64` is deliberate here.
fn assert_exact(actual: f64, expected: f64, what: &str) {
    assert_eq!(
        actual.to_bits(),
        expected.to_bits(),
        "{what}: {actual:?} != {expected:?}"
    );
}

#[test]
fn travel_costs_match_python_exactly() {
    for (index, case) in load().travel.iter().enumerate() {
        assert_exact(
            model(&case.model).travel_cost_wh(f(&case.distance_m)),
            f(&case.expected),
            &format!("travel[{index}] distance {}", case.distance_m),
        );
    }
}

#[test]
fn climb_costs_match_python_exactly() {
    for (index, case) in load().climb.iter().enumerate() {
        assert_exact(
            model(&case.model).climb_cost_wh(f(&case.delta_z_m)),
            f(&case.expected),
            &format!("climb[{index}] delta_z {}", case.delta_z_m),
        );
    }
}

#[test]
fn segment_costs_match_python_exactly() {
    for (index, case) in load().segment.iter().enumerate() {
        assert_exact(
            model(&case.model).segment_cost_wh(triple(&case.start), triple(&case.end)),
            f(&case.expected),
            &format!("segment[{index}]"),
        );
    }
}

#[test]
fn return_home_and_reserve_match_python_exactly() {
    let fixture = load();
    let margin = f(&fixture.default_safety_margin);
    assert_eq!(margin, BatteryModel::DEFAULT_SAFETY_MARGIN);
    for (index, case) in fixture.return_home.iter().enumerate() {
        let m = model(&case.model);
        let wind = case.wind.as_ref().map(triple);
        assert_exact(
            m.return_home_cost_wh(triple(&case.position), triple(&case.home), wind),
            f(&case.expected_return_cost_wh),
            &format!("return_home[{index}]"),
        );
        assert_exact(
            m.dynamic_reserve_wh(triple(&case.position), triple(&case.home), wind, margin),
            f(&case.expected_dynamic_reserve_wh),
            &format!("dynamic_reserve[{index}]"),
        );
    }
}

#[test]
fn consume_matches_python_exactly() {
    for (index, case) in load().consume.iter().enumerate() {
        let before = BatteryState {
            remaining_wh: f(&case.before_remaining_wh),
            timestamp_s: f(&case.before_timestamp_s),
        };
        let after = before.consume(f(&case.cost_wh));
        assert_exact(
            after.remaining_wh,
            f(&case.after_remaining_wh),
            &format!("consume[{index}] remaining"),
        );
        assert_exact(
            after.timestamp_s,
            f(&case.after_timestamp_s),
            &format!("consume[{index}] timestamp"),
        );
    }
}

// ---------------------------------------------------------------------------
// Coverage: the fixture must actually reach the branches it claims to.
// ---------------------------------------------------------------------------

/// A port that collapsed the climb/descent split would pass a fixture that
/// only ever climbed. Assert both sides are present, and that exactly zero
/// takes the DESCENT branch -- the reference tests `delta_z_m > 0`.
#[test]
fn the_fixture_reaches_both_sides_of_the_climb_descent_split() {
    let fixture = load();
    let mut climbs = 0;
    let mut descents = 0;
    let mut saw_zero = false;
    for case in &fixture.climb {
        let delta = f(&case.delta_z_m);
        if delta > 0.0 {
            climbs += 1;
        } else {
            descents += 1;
        }
        if delta == 0.0 {
            saw_zero = true;
            assert_eq!(
                f(&case.expected),
                0.0,
                "a zero delta costs nothing whichever power it picks"
            );
        }
    }
    assert!(
        climbs > 0 && descents > 0,
        "both branches must be exercised"
    );
    assert!(
        saw_zero,
        "exactly zero must be covered; it takes the descent branch"
    );

    // And the two powers really are different, so the branch is observable.
    let m = BatteryModel::default();
    assert_ne!(m.climb_cost_wh(10.0), m.climb_cost_wh(-10.0));
}

/// The static reserve is a floor. The fixture must contain cases on both
/// sides of it, or a port that dropped the `max` would pass.
#[test]
fn the_fixture_reaches_both_sides_of_the_static_reserve_floor() {
    let fixture = load();
    let mut floored = 0;
    let mut dynamic_wins = 0;
    for case in &fixture.return_home {
        let reserve = f(&case.expected_dynamic_reserve_wh);
        let static_reserve = f(&case.static_reserve_wh);
        if reserve == static_reserve {
            floored += 1;
        } else {
            assert!(
                reserve > static_reserve,
                "the dynamic reserve may only exceed the floor, never fall below it"
            );
            dynamic_wins += 1;
        }
    }
    assert!(
        floored > 0,
        "no case where the static floor binds; dropping the max would pass"
    );
    assert!(
        dynamic_wins > 0,
        "no case where the dynamic estimate exceeds the floor"
    );
}

/// Head- and tailwind must both appear, and in the right direction: a headwind
/// costs more than still air, a tailwind less.
#[test]
fn wind_moves_the_return_cost_in_the_expected_direction() {
    let m = BatteryModel::default();
    let position = [1000.0, 0.0, 120.0];
    let home = [0.0, 0.0, 20.0];
    let still = m.return_home_cost_wh(position, home, None);
    // Home lies in -x, so a +x wind opposes the track: a headwind.
    let headwind = m.return_home_cost_wh(position, home, Some([5.0, 0.0, 0.0]));
    let tailwind = m.return_home_cost_wh(position, home, Some([-5.0, 0.0, 0.0]));
    assert!(headwind > still, "a headwind must cost more");
    assert!(tailwind < still, "a tailwind must cost less");

    // The groundspeed floor caps how bad a headwind can get.
    let gale = m.return_home_cost_wh(position, home, Some([1000.0, 0.0, 0.0]));
    let extreme = m.return_home_cost_wh(position, home, Some([1e6, 0.0, 0.0]));
    assert_eq!(
        gale, extreme,
        "past the floor, more headwind must not raise the cost further"
    );
}

/// `gale == extreme` above proves a floor exists but not *where* it is: it
/// holds for any floor value. Pin the value itself.
///
/// Flown level, the whole cost is the travel term, which is inversely
/// proportional to groundspeed. A floor at 25% of cruise therefore makes the
/// floored cost exactly four times the still-air cost -- and exactly, not
/// approximately, because scaling a quotient by 4 is a power-of-two exponent
/// bump that cannot change the mantissa.
#[test]
fn the_groundspeed_floor_sits_at_a_quarter_of_cruise() {
    let m = BatteryModel::default();
    // Level flight, so `climb_cost_wh` contributes exactly zero and cannot
    // blur the ratio.
    let position = [1000.0, 0.0, 20.0];
    let home = [0.0, 0.0, 20.0];
    let still = m.return_home_cost_wh(position, home, None);
    let floored = m.return_home_cost_wh(position, home, Some([1e6, 0.0, 0.0]));
    assert_exact(
        floored,
        4.0 * still,
        "floored cost is 4x the still-air cost",
    );

    // A headwind that lands short of the floor must not be clamped to it: the
    // floor is a `max`, not the only branch. A 5 m/s headwind against a 10 m/s
    // cruise leaves 5 m/s of groundspeed -- double the 2.5 m/s floor -- so the
    // cost is exactly twice still air, again a power-of-two ratio.
    let below_floor = m.return_home_cost_wh(position, home, Some([5.0, 0.0, 0.0]));
    assert!(
        below_floor < floored,
        "a headwind short of the floor must cost less than the floored case"
    );
    assert_exact(
        below_floor,
        2.0 * still,
        "short of the floor the cost tracks the actual groundspeed",
    );
}

/// The wind guard is `distance_m > 1e-6`, not `> 0`. The no-separation case
/// cannot tell the two apart -- both reject a distance of exactly zero -- so
/// the threshold needs a track that is short but genuinely non-zero.
#[test]
fn the_wind_guard_ignores_a_track_shorter_than_a_micron() {
    let m = BatteryModel::default();
    let position = [5e-7, 0.0, 120.0];
    let home = [0.0, 0.0, 20.0];
    let still = m.return_home_cost_wh(position, home, None);
    // A 50 m/s headwind would drive the groundspeed to the 2.5 m/s floor and
    // quadruple the travel term -- if the guard let it through.
    assert_exact(
        m.return_home_cost_wh(position, home, Some([50.0, 0.0, 0.0])),
        still,
        "a sub-micron track resolves no wind",
    );
    // And just above the threshold it does apply, so the guard is a threshold
    // rather than a blanket refusal to ever use wind on a short track.
    let above = [2e-6, 0.0, 120.0];
    assert_ne!(
        m.return_home_cost_wh(above, home, Some([50.0, 0.0, 0.0])),
        m.return_home_cost_wh(above, home, None),
        "past 1e-6 the wind must be resolved"
    );
}

/// The fixture -- not just the unit tests above -- must reach the groundspeed
/// floor and the sub-threshold track, or Python parity would never see either.
#[test]
fn the_fixture_reaches_the_groundspeed_floor_and_the_wind_guard() {
    let fixture = load();
    let mut floored = 0;
    let mut short_track_with_wind = 0;
    let mut wind_actually_applied = 0;
    for case in &fixture.return_home {
        let m = model(&case.model);
        let distance = f(&case.horizontal_distance_m);
        let ground_speed = f(&case.ground_speed_m_per_s);
        let floor = 0.25 * m.cruise_speed_m_per_s;
        if case.wind.is_some() && ground_speed == floor {
            floored += 1;
        }
        if case.wind.is_some() && distance > 0.0 && distance <= 1e-6 {
            short_track_with_wind += 1;
            assert_eq!(
                ground_speed,
                m.cruise_speed_m_per_s.max(0.01),
                "a sub-threshold track must leave the groundspeed at cruise"
            );
        }
        if case.wind.is_some() && ground_speed != m.cruise_speed_m_per_s.max(0.01) {
            wind_actually_applied += 1;
        }
    }
    assert!(
        floored > 0,
        "no fixture case reaches the groundspeed floor; its value is unpinned"
    );
    assert!(
        short_track_with_wind > 0,
        "no fixture case has a non-zero track below the 1e-6 guard"
    );
    assert!(
        wind_actually_applied > 0,
        "no fixture case applies wind at all"
    );
}

/// Crosswind has no along-track component, so it must not change the cost.
#[test]
fn a_pure_crosswind_does_not_change_the_return_cost() {
    let m = BatteryModel::default();
    let position = [1000.0, 0.0, 120.0];
    let home = [0.0, 0.0, 20.0];
    assert_eq!(
        m.return_home_cost_wh(position, home, None),
        m.return_home_cost_wh(position, home, Some([0.0, 25.0, 0.0]))
    );
}

/// With no horizontal separation there is no track to resolve wind onto, so
/// the wind is ignored entirely rather than dividing by a near-zero distance.
#[test]
fn wind_is_ignored_when_there_is_no_horizontal_track() {
    let m = BatteryModel::default();
    let position = [0.0, 0.0, 120.0];
    let home = [0.0, 0.0, 20.0];
    assert_eq!(
        m.return_home_cost_wh(position, home, None),
        m.return_home_cost_wh(position, home, Some([50.0, 50.0, 0.0]))
    );
}

/// Consuming past empty clamps at zero rather than going negative, and a
/// negative cost adds energy back -- which the reference does not guard
/// against, so neither does this.
#[test]
fn consume_clamps_at_empty_and_does_not_guard_negative_costs() {
    let state = BatteryState {
        remaining_wh: 5.0,
        timestamp_s: 1.0,
    };
    assert_eq!(state.consume(1000.0).remaining_wh, 0.0);
    assert_eq!(state.consume(-3.0).remaining_wh, 8.0);
    assert_eq!(
        state.consume(2.0).timestamp_s,
        1.0,
        "the reference carries the timestamp through unchanged"
    );
}

/// **An equivalent mutant, recorded rather than tested around.**
///
/// Mutation testing flipped `delta_z_m > 0.0` to `>= 0.0` in `climb_cost_wh`
/// and no test failed. That is not a gap in the tests -- no test *can* fail,
/// because no input distinguishes the two operators:
///
/// * for any `delta_z_m != 0` the two comparisons agree, so the same power is
///   selected;
/// * at `delta_z_m == 0` (and at `-0.0`, where they disagree) the duration is
///   `0.0.abs() / speed == 0.0`, and `power * 0.0 / 3600.0` is `+0.0` for
///   every finite power, so the selection is unobservable;
/// * `NaN` fails both comparisons identically.
///
/// This test states the proof as executable assertions. It would be dishonest
/// to add a test that "catches" the mutation by asserting which power a zero
/// delta picks, since the reference does not expose that either.
#[test]
fn the_climb_comparison_operator_is_unobservable_at_a_zero_delta() {
    // A model whose two powers are wildly different, so if the selection were
    // observable at zero it would be obvious.
    let m = BatteryModel {
        climb_power_w: 1.0e9,
        hover_power_w: 1.0,
        ..BatteryModel::default()
    };
    assert_exact(m.climb_cost_wh(0.0), 0.0, "a zero delta costs nothing");
    assert_exact(m.climb_cost_wh(-0.0), 0.0, "and so does negative zero");
    assert!(
        !m.climb_cost_wh(0.0).is_sign_negative(),
        "the result is +0.0, not -0.0, so even the sign bit cannot tell them apart"
    );

    // Away from zero the operators cannot disagree. Asserting
    // `delta > 0.0 && delta >= 0.0` here would be the natural way to say so,
    // but `clippy::redundant_comparisons` rejects it at compile time on
    // exactly the grounds this proof rests on -- "if `delta > 0.0` evaluates
    // to true, `delta >= 0.0` will always evaluate to true as well". A static
    // proof beats a runtime one, so the assertion is left to clippy and what
    // remains is the part that is not tautological: the two powers really do
    // differ away from zero, which is what makes the branch worth having.
    for delta in [f64::MIN_POSITIVE, 1e-9, 1.0, 5000.0] {
        assert_ne!(m.climb_cost_wh(delta), m.climb_cost_wh(-delta));
    }

    assert!(
        f64::NAN.partial_cmp(&0.0).is_none(),
        "NaN fails both comparisons, so it cannot separate them either"
    );
}

/// The `fraction_of` helper this port adds must agree with what `sim.py`
/// computes by hand, since the reference's `fraction` property returns
/// watt-hours and is used nowhere.
#[test]
fn fraction_of_matches_what_the_simulation_computes_by_hand() {
    let state = BatteryState {
        remaining_wh: 25.0,
        timestamp_s: 0.0,
    };
    assert_eq!(state.fraction_of(100.0), 0.25);
    assert_eq!(state.fraction_of(0.0), 0.0, "no capacity is not a division");
}
